# EVOLVE-BLOCK-START
#pragma GCC optimize("O3,unroll-loops")

#include <iostream>
#include <vector>
#include <string>
#include <numeric>
#include <algorithm>
#include <chrono>
#include <random>
#include <iomanip> 
#include <cmath>   
#include <functional>
#include <queue>
// #include <map> // Not used

// Global game data
int N_GRID_SIZE; 
std::vector<std::string> H_WALLS_INFO; 
std::vector<std::string> V_WALLS_INFO; 
int D_SUSC[40][40];

struct Pos {
    int16_t r, c;
    Pos() : r(0), c(0) {} 
    Pos(int16_t r_val, int16_t c_val) : r(r_val), c(c_val) {}

    bool operator==(const Pos& other) const { return r == other.r && c == other.c; }
    bool operator!=(const Pos& other) const { return !(*this == other); }
    bool operator<(const Pos& other) const { 
        if (r != other.r) return r < other.r;
        return c < other.c;
    }
};

constexpr int DR[] = {0, 1, 0, -1}; // R, D, L, U
constexpr int DC[] = {1, 0, -1, 0};
constexpr char DIR_CHARS[] = {'R', 'D', 'L', 'U'};
const int MAX_L_PATH = 100000; 
double MAX_L_PATH_HIGH_THRESHOLD_EFFECTIVE; 
double MIN_L_PATH_LOW_THRESHOLD_EFFECTIVE;  


std::mt19937 RND_ENGINE; 

Pos APSP_PARENT[40][40][40][40]; 
int APSP_DIST[40][40][40][40];   

bool is_valid_pos(int r, int c) {
    return r >= 0 && r < N_GRID_SIZE && c >= 0 && c < N_GRID_SIZE;
}

bool check_wall(Pos p_from, Pos p_to) {
    int dr = p_to.r - p_from.r;
    int dc = p_to.c - p_from.c;
    if (dr == 1) { // Down
        return H_WALLS_INFO[p_from.r][p_from.c] == '1';
    } else if (dr == -1) { // Up
        return H_WALLS_INFO[p_to.r][p_to.c] == '1';
    } else if (dc == 1) { // Right
        return V_WALLS_INFO[p_from.r][p_from.c] == '1';
    } else if (dc == -1) { // Left
        return V_WALLS_INFO[p_from.r][p_to.c] == '1';
    }
    return true; 
}

char get_move_char(Pos p_from, Pos p_to) {
    int dr = p_to.r - p_from.r;
    int dc = p_to.c - p_from.c;
    for(int i=0; i<4; ++i) if(DR[i] == dr && DC[i] == dc) return DIR_CHARS[i];
    return ' '; 
}

char invert_move(char move_char) {
    for(int i=0; i<4; ++i) if(DIR_CHARS[i] == move_char) return DIR_CHARS[(i+2)%4];
    return ' ';
}

void compute_apsp() {
    for (int sr = 0; sr < N_GRID_SIZE; ++sr) {
        for (int sc = 0; sc < N_GRID_SIZE; ++sc) {
            for (int tr = 0; tr < N_GRID_SIZE; ++tr) for (int tc = 0; tc < N_GRID_SIZE; ++tc) APSP_DIST[sr][sc][tr][tc] = -1; 

            std::vector<Pos> q; q.reserve(N_GRID_SIZE * N_GRID_SIZE);
            q.push_back(Pos{(int16_t)sr, (int16_t)sc});
            APSP_DIST[sr][sc][sr][sc] = 0;

            int head = 0;
            while(head < static_cast<int>(q.size())){
                Pos curr = q[head++];
                for(int i=0; i<4; ++i){
                    Pos next_candidate = Pos{(int16_t)(curr.r + DR[i]), (int16_t)(curr.c + DC[i])};
                    if(is_valid_pos(next_candidate.r, next_candidate.c) && !check_wall(curr, next_candidate) && APSP_DIST[sr][sc][next_candidate.r][next_candidate.c] == -1){
                        APSP_DIST[sr][sc][next_candidate.r][next_candidate.c] = APSP_DIST[sr][sc][curr.r][curr.c] + 1;
                        APSP_PARENT[sr][sc][next_candidate.r][next_candidate.c] = curr;
                        q.push_back(next_candidate);
                    }
                }
            }
        }
    }
}

bool get_apsp_moves(Pos p_from, Pos p_to, std::vector<char>& out_moves) {
    out_moves.clear();
    if (p_from == p_to) return true;
    if (APSP_DIST[p_from.r][p_from.c][p_to.r][p_to.c] == -1) return false; 

    out_moves.reserve(APSP_DIST[p_from.r][p_from.c][p_to.r][p_to.c]);
    Pos curr = p_to;
    while(curr != p_from) {
       Pos prev = APSP_PARENT[p_from.r][p_from.c][curr.r][curr.c];
       out_moves.push_back(get_move_char(prev, curr));
       curr = prev;
    }
    std::reverse(out_moves.begin(), out_moves.end());
    return true;
}

std::vector<std::vector<std::vector<int>>> CELL_VISIT_TIMES_GLOBAL_BUFFER; 

struct CellDirtInfo {
    long double weighted_dirt_contribution;
    Pos p;
    bool operator<(const CellDirtInfo& other) const {
        return weighted_dirt_contribution > other.weighted_dirt_contribution; 
    }
};
std::vector<CellDirtInfo> TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER; 

struct PathData {
    std::vector<char> moves;
    std::vector<Pos> coords; 
    bool visited_flags[40][40]; 
    long double score_val;
    long double total_dirt_sum_numerator; 
    long double cell_dirt_term_sum[40][40]; 

    PathData() : score_val(1e18L), total_dirt_sum_numerator(0.0L) {
        for(int i=0; i<N_GRID_SIZE; ++i) for(int j=0; j<N_GRID_SIZE; ++j) { 
            visited_flags[i][j] = false;
            cell_dirt_term_sum[i][j] = 0.0L;
        }
    }

    PathData(const PathData& other) = default;
    PathData(PathData&& other) = default;
    PathData& operator=(const PathData& other) = default;
    PathData& operator=(PathData&& other) = default;
};

bool update_coords_and_visited_flags(PathData& pd) {
    pd.coords.assign(1, Pos{0,0}); 
    if (!pd.moves.empty()) { 
      pd.coords.reserve(pd.moves.size() + 1); 
    }

    for (int r = 0; r < N_GRID_SIZE; ++r) for (int c = 0; c < N_GRID_SIZE; ++c) pd.visited_flags[r][c] = false;
    pd.visited_flags[0][0] = true;

    Pos current_p = Pos{0,0};
    for (char move_char : pd.moves) {
        int dir_idx = -1;
        for (int i = 0; i < 4; ++i) if (DIR_CHARS[i] == move_char) dir_idx = i;

        if (dir_idx == -1) return false; 

        Pos next_p = Pos{(int16_t)(current_p.r + DR[dir_idx]), (int16_t)(current_p.c + DC[dir_idx])};
        if (!is_valid_pos(next_p.r, next_p.c) || check_wall(current_p, next_p)) return false; 

        current_p = next_p;
        pd.coords.push_back(current_p);
        pd.visited_flags[current_p.r][current_p.c] = true;
    }
    return true;
}

void calculate_score_full(PathData& pd) {
    if (!update_coords_and_visited_flags(pd)) {
        pd.score_val = 1e18L; 
        return;
    }

    if (pd.moves.size() > MAX_L_PATH) {
        pd.score_val = 1e18L; return;
    }
    if (!pd.moves.empty()){ 
        if (pd.coords.back() != Pos{0,0}) { pd.score_val = 1e18L; return;}
    } else { 
        if (N_GRID_SIZE > 1) { 
             pd.score_val = 1e18L; return;
        }
    }

    for (int r = 0; r < N_GRID_SIZE; ++r) for (int c = 0; c < N_GRID_SIZE; ++c) {
        if (!pd.visited_flags[r][c]) { pd.score_val = 1e18L; return; }
    }

    int L = pd.moves.size();

    if (L == 0) { 
       pd.score_val = (N_GRID_SIZE == 1) ? 0.0L : 1e18L; // N=1 case not in this contest
       pd.total_dirt_sum_numerator = 0;
       if (N_GRID_SIZE == 1) pd.cell_dirt_term_sum[0][0] = 0;
       return;
    }

    for(int r=0; r<N_GRID_SIZE; ++r) {
        for(int c=0; c<N_GRID_SIZE; ++c) {
            CELL_VISIT_TIMES_GLOBAL_BUFFER[r][c].clear(); 
        }
    }

    for (int t = 1; t <= L; ++t) { 
        Pos p = pd.coords[t]; 
        CELL_VISIT_TIMES_GLOBAL_BUFFER[p.r][p.c].push_back(t);
    }

    pd.total_dirt_sum_numerator = 0;

    for (int r_ = 0; r_ < N_GRID_SIZE; ++r_) {
        for (int c_ = 0; c_ < N_GRID_SIZE; ++c_) {
            const auto& specific_cell_visits = CELL_VISIT_TIMES_GLOBAL_BUFFER[r_][c_];
            long double current_cell_dirt_term = 0; 

            if (!specific_cell_visits.empty()){
                 int num_visits_in_cycle = specific_cell_visits.size();
                 for (int i = 0; i < num_visits_in_cycle; ++i) {
                    long long prev_visit_t = (i == 0) ? ((long long)specific_cell_visits[num_visits_in_cycle - 1] - L) : (long long)specific_cell_visits[i-1];
                    long long cur_visit_t = specific_cell_visits[i];
                    long long delta = cur_visit_t - prev_visit_t; 
                    current_cell_dirt_term += (long double)delta * (delta - 1) / 2.0L;
                }
            } else { 
                current_cell_dirt_term = (long double)L * (L - 1) / 2.0L;
            }
            pd.cell_dirt_term_sum[r_][c_] = current_cell_dirt_term;
            pd.total_dirt_sum_numerator += (long double)D_SUSC[r_][c_] * current_cell_dirt_term;
        }
    }
    pd.score_val = pd.total_dirt_sum_numerator / L;
}

bool initial_dfs_visited[40][40]; 

void calculate_score_full(PathData& pd);

void generate_initial_dfs_path(int r, int c, PathData& pd) {
    // Build three susceptibility-threshold macrocycles and keep the best exact-scored route.
    using MoveList = std::vector<char>;

    auto append_shortest = [&](MoveList& route, Pos from, Pos to) -> bool {
        if (APSP_DIST[from.r][from.c][to.r][to.c] < 0) return false;

        Pos cur = to;
        MoveList reversed;
        reversed.reserve(APSP_DIST[from.r][from.c][to.r][to.c]);

        while (cur != from) {
            Pos prev = APSP_PARENT[from.r][from.c][cur.r][cur.c];
            reversed.push_back(get_move_char(prev, cur));
            cur = prev;
        }

        route.insert(route.end(), reversed.rbegin(), reversed.rend());
        return true;
    };

    auto build_macrocycle = [&](int percentile) -> MoveList {
        MoveList route;

        std::vector<int> sorted_values;
        sorted_values.reserve(N_GRID_SIZE * N_GRID_SIZE);
        for (int i = 0; i < N_GRID_SIZE; ++i)
            for (int j = 0; j < N_GRID_SIZE; ++j)
                sorted_values.push_back(D_SUSC[i][j]);

        std::sort(sorted_values.begin(), sorted_values.end());
        int threshold =
            sorted_values[(sorted_values.size() - 1) * percentile / 100];
        int median_value = sorted_values[sorted_values.size() / 2];

        // Mandatory coverage backbone over the whole reachable board.
        bool covered[40][40] = {};
        std::function<void(Pos)> cover = [&](Pos u) {
            covered[u.r][u.c] = true;

            for (int dir = 0; dir < 4; ++dir) {
                Pos v{(int16_t)(u.r + DR[dir]),
                      (int16_t)(u.c + DC[dir])};

                if (!is_valid_pos(v.r, v.c) ||
                    covered[v.r][v.c] ||
                    check_wall(u, v))
                    continue;

                route.push_back(DIR_CHARS[dir]);
                cover(v);
                route.push_back(DIR_CHARS[(dir + 2) % 4]);
            }
        };
        cover(Pos{0, 0});

        bool component_used[40][40] = {};
        std::vector<Pos> anchors;
        std::vector<int> component_sums;
        std::vector<MoveList> patrols;

        // Extract hot connected components and construct one closed patrol per component.
        for (int sr = 0; sr < N_GRID_SIZE; ++sr) {
            for (int sc = 0; sc < N_GRID_SIZE; ++sc) {
                if (component_used[sr][sc] ||
                    D_SUSC[sr][sc] < threshold)
                    continue;

                std::vector<Pos> component;
                std::vector<Pos> queue;
                queue.push_back(Pos{(int16_t)sr, (int16_t)sc});
                component_used[sr][sc] = true;

                for (size_t head = 0; head < queue.size(); ++head) {
                    Pos u = queue[head];
                    component.push_back(u);

                    for (int dir = 0; dir < 4; ++dir) {
                        Pos v{(int16_t)(u.r + DR[dir]),
                              (int16_t)(u.c + DC[dir])};

                        if (!is_valid_pos(v.r, v.c) ||
                            component_used[v.r][v.c] ||
                            D_SUSC[v.r][v.c] < threshold ||
                            check_wall(u, v))
                            continue;

                        component_used[v.r][v.c] = true;
                        queue.push_back(v);
                    }
                }

                Pos anchor = component.front();
                int component_sum = 0;
                for (Pos u : component) {
                    component_sum += D_SUSC[u.r][u.c];
                    if (D_SUSC[u.r][u.c] > D_SUSC[anchor.r][anchor.c])
                        anchor = u;
                }

                MoveList patrol;
                bool local_used[40][40] = {};

                // Iterative DFS creates an Euler-style closed walk of the
                // component spanning tree, beginning and ending at anchor.
                struct Frame {
                    Pos position;
                    int next_direction;
                };

                std::vector<Frame> stack;
                stack.push_back({anchor, 0});
                local_used[anchor.r][anchor.c] = true;

                while (!stack.empty()) {
                    Frame& frame = stack.back();
                    bool descended = false;

                    while (frame.next_direction < 4) {
                        int dir = frame.next_direction++;
                        Pos u = frame.position;
                        Pos v{(int16_t)(u.r + DR[dir]),
                              (int16_t)(u.c + DC[dir])};

                        if (!is_valid_pos(v.r, v.c) ||
                            local_used[v.r][v.c] ||
                            D_SUSC[v.r][v.c] < threshold ||
                            check_wall(u, v))
                            continue;

                        local_used[v.r][v.c] = true;
                        patrol.push_back(DIR_CHARS[dir]);
                        stack.push_back({v, 0});
                        descended = true;
                        break;
                    }

                    if (descended) continue;

                    Pos finished = frame.position;
                    stack.pop_back();

                    if (!stack.empty()) {
                        Pos parent = stack.back().position;
                        int back_direction = 0;
                        while (parent.r + DR[back_direction] != finished.r ||
                               parent.c + DC[back_direction] != finished.c)
                            ++back_direction;

                        patrol.push_back(
                            DIR_CHARS[(back_direction + 2) % 4]);
                    }
                }

                anchors.push_back(anchor);
                component_sums.push_back(component_sum);
                patrols.push_back(std::move(patrol));
            }
        }

        // Visit anchors in nearest-neighbor order from the origin.
        std::vector<int> order(anchors.size());
        std::iota(order.begin(), order.end(), 0);

        Pos current{0, 0};
        for (size_t out = 0; out < order.size(); ++out) {
            size_t best = out;
            int best_distance =
                APSP_DIST[current.r][current.c]
                         [anchors[order[best]].r][anchors[order[best]].c];

            for (size_t k = out + 1; k < order.size(); ++k) {
                int distance =
                    APSP_DIST[current.r][current.c]
                             [anchors[order[k]].r][anchors[order[k]].c];

                if (distance >= 0 &&
                    (best_distance < 0 || distance < best_distance)) {
                    best = k;
                    best_distance = distance;
                }
            }

            std::swap(order[out], order[best]);
            int component_id = order[out];
            Pos anchor = anchors[component_id];

            if (!append_shortest(route, current, anchor))
                continue;

            const int denominator =
                std::max(1, median_value * 8);
            int repeats =
                1 + component_sums[component_id] / denominator;
            repeats = std::min(repeats, 8);

            for (int rep = 0; rep < repeats; ++rep) {
                if (route.size() + patrols[component_id].size() >
                    MAX_L_PATH)
                    break;

                route.insert(route.end(),
                             patrols[component_id].begin(),
                             patrols[component_id].end());
            }

            current = anchor;
        }

        append_shortest(route, current, Pos{0, 0});
        return route;
    };

    // Compare exactly the requested three deterministic susceptibility cuts.
    PathData constructed_best;
    constructed_best.score_val = 1e18L;

    for (int percentile : {35, 60, 82}) {
        PathData candidate;
        candidate.moves = build_macrocycle(percentile);

        if (candidate.moves.size() > MAX_L_PATH)
            continue;

        calculate_score_full(candidate);
        if (candidate.score_val < constructed_best.score_val)
            constructed_best = std::move(candidate);
    }

    if (constructed_best.score_val < 1e17L)
        pd = std::move(constructed_best);
    else {
        // Preserve the original legal DFS fallback if every macrocycle
        // exceeds the output limit.
        initial_dfs_visited[r][c] = true;
        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
            Pos current_p{(int16_t)r, (int16_t)c};
            Pos next_p{(int16_t)(r + DR[dir_idx]),
                       (int16_t)(c + DC[dir_idx])};

            if (is_valid_pos(next_p.r, next_p.c) &&
                !check_wall(current_p, next_p) &&
                !initial_dfs_visited[next_p.r][next_p.c]) {
                pd.moves.push_back(DIR_CHARS[dir_idx]);
                generate_initial_dfs_path(next_p.r, next_p.c, pd);
                pd.moves.push_back(DIR_CHARS[(dir_idx + 2) % 4]);
            }
        }
    }
}

Pos select_target_cell_for_dirt_ops(const PathData& current_pd_obj, bool use_sqrt_N_sampling) {
    TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.clear(); 
    if (current_pd_obj.score_val > 1e17L) { 
        std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
        return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    for(int r=0; r<N_GRID_SIZE; ++r) {
        for(int c=0; c<N_GRID_SIZE; ++c) {
             TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.push_back({(long double)D_SUSC[r][c] * current_pd_obj.cell_dirt_term_sum[r][c], Pos{(int16_t)r,(int16_t)c}});
        }
    }
    std::sort(TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.begin(), TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.end());

    if (TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.empty()) { 
        std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
        return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    int K_select;
    if(use_sqrt_N_sampling){ 
        K_select = std::min((int)TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.size(), std::max(1, N_GRID_SIZE));
    } else { 
        K_select = std::min((int)TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.size(), std::max(10, N_GRID_SIZE * N_GRID_SIZE / 10));
    }

    if (K_select <= 0) { 
         std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
         return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    std::uniform_int_distribution<int> top_k_dist(0, K_select - 1);
    return TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER[top_k_dist(RND_ENGINE)].p;
}

const int OP4_SAMPLE_POINTS = 20; 
const int OP5_MAX_SUBSEGMENT_LEN = 20; 

std::vector<char> GET_APSP_MOVES_BUFFER1;
std::vector<char> GET_APSP_MOVES_BUFFER2;

/**
 * Build four bounded global service schedules.
 *
 * Each schedule repeatedly selects the most urgent cell according to its
 * dirt susceptibility and estimated age, divided by travel cost.  During the
 * initial coverage phase every unvisited cell is prioritized.  APSP paths are
 * appended directly, and the resulting closed route is scored exactly.
 */
PathData generate_service_schedule_seed() {
    PathData best;
    best.score_val = 1e18L;

    const double exponents[4] = {1.5, 1.8, 2.1, 2.4};
    const int cells = N_GRID_SIZE * N_GRID_SIZE;

    for (int start_id = 0; start_id < 4; ++start_id) {
        std::vector<char> route;
        route.reserve(50000);
        std::vector<int> last_visit(cells, 0);
        std::vector<unsigned char> seen(cells, 0);

        Pos current{0, 0};
        int elapsed = 0;
        int covered = 1;
        seen[0] = 1;

        // The initial age estimate favors cells that are far from the origin.
        for (int r = 0; r < N_GRID_SIZE; ++r) {
            for (int c = 0; c < N_GRID_SIZE; ++c) {
                int id = r * N_GRID_SIZE + c;
                last_visit[id] = -2 * APSP_DIST[0][0][r][c] - 1;
            }
        }
        last_visit[0] = 0;

        for (int waypoint = 0; waypoint < 5000; ++waypoint) {
            Pos target{-1, -1};
            double best_value = -1.0;

            // Complete coverage is mandatory, so unvisited cells override
            // the ordinary urgency score.
            if (covered < cells) {
                for (int r = 0; r < N_GRID_SIZE; ++r) {
                    for (int c = 0; c < N_GRID_SIZE; ++c) {
                        int id = r * N_GRID_SIZE + c;
                        if (seen[id]) continue;
                        int dist = APSP_DIST[current.r][current.c][r][c];
                        if (dist < 0) continue;
                        double value = static_cast<double>(D_SUSC[r][c]) /
                                       (1.0 + dist);
                        if (target.r < 0 || value > best_value) {
                            best_value = value;
                            target = Pos{(int16_t)r, (int16_t)c};
                        }
                    }
                }
            } else {
                for (int r = 0; r < N_GRID_SIZE; ++r) {
                    for (int c = 0; c < N_GRID_SIZE; ++c) {
                        int dist = APSP_DIST[current.r][current.c][r][c];
                        if (dist < 0) continue;
                        int id = r * N_GRID_SIZE + c;
                        double age = std::max(1, elapsed - last_visit[id]);
                        double predicted = age + dist + 1.0;
                        double value =
                            static_cast<double>(D_SUSC[r][c]) *
                            std::pow(predicted, exponents[start_id]) /
                            std::max(1, dist);
                        if (target.r < 0 || value > best_value) {
                            best_value = value;
                            target = Pos{(int16_t)r, (int16_t)c};
                        }
                    }
                }
            }

            if (target.r < 0) break;
            if (!get_apsp_moves(current, target, GET_APSP_MOVES_BUFFER1))
                break;

            if (route.size() + GET_APSP_MOVES_BUFFER1.size() > 50000)
                break;

            for (char move : GET_APSP_MOVES_BUFFER1) route.push_back(move);

            Pos walk = current;
            last_visit[walk.r * N_GRID_SIZE + walk.c] = elapsed;
            for (char move : GET_APSP_MOVES_BUFFER1) {
                int dir = 0;
                while (DIR_CHARS[dir] != move) ++dir;
                walk.r += DR[dir];
                walk.c += DC[dir];
                ++elapsed;
                int id = walk.r * N_GRID_SIZE + walk.c;
                if (!seen[id]) {
                    seen[id] = 1;
                    ++covered;
                }
                last_visit[id] = elapsed;
            }
            current = target;
        }

        if (covered != cells) continue;
        if (!get_apsp_moves(current, Pos{0, 0}, GET_APSP_MOVES_BUFFER1))
            continue;
        if (route.size() + GET_APSP_MOVES_BUFFER1.size() > MAX_L_PATH)
            continue;
        route.insert(route.end(), GET_APSP_MOVES_BUFFER1.begin(),
                     GET_APSP_MOVES_BUFFER1.end());

        PathData candidate;
        candidate.moves = std::move(route);
        calculate_score_full(candidate);
        if (candidate.score_val < best.score_val)
            best = std::move(candidate);
    }

    return best;
}


/**
 * Construct demand-weighted rooted-tree circulation candidates.
 *
 * Six deterministic BFS spanning trees are built using high-demand,
 * low-demand, geometric, and two deterministic weight-biased neighbor
 * orders.  Each candidate starts with a complete Euler tour, then adds
 * feasible closed excursions into subtrees with the largest
 * demand*(age+round_trip_cost)^2/cost priority.  The serviced subtree
 * ages are reset to zero, while all other cells age by the excursion
 * length.  Every candidate is scored exactly and the best is returned.
 */
PathData generate_weighted_tree_circulation() {
    PathData best;
    best.score_val = 1e18L;

    const int cells = N_GRID_SIZE * N_GRID_SIZE;

    for (int variant = 0; variant < 6; ++variant) {
        std::vector<int> parent(cells, -1);
        std::vector<int> depth(cells, 0);
        std::vector<std::vector<int>> children(cells);
        std::vector<int> order;
        order.reserve(cells);

        auto id_of = [&](int r, int c) {
            return r * N_GRID_SIZE + c;
        };
        auto pos_of = [&](int id) {
            return Pos{static_cast<int16_t>(id / N_GRID_SIZE),
                       static_cast<int16_t>(id % N_GRID_SIZE)};
        };

        auto ordered_dirs = [&](Pos u) {
            std::vector<int> dirs = {0, 1, 2, 3};

            if (variant == 0 || variant == 1 || variant >= 4) {
                std::sort(dirs.begin(), dirs.end(), [&](int a, int b) {
                    Pos pa{static_cast<int16_t>(u.r + DR[a]),
                           static_cast<int16_t>(u.c + DC[a])};
                    Pos pb{static_cast<int16_t>(u.r + DR[b]),
                           static_cast<int16_t>(u.c + DC[b])};

                    if (!is_valid_pos(pa.r, pa.c))
                        return false;
                    if (!is_valid_pos(pb.r, pb.c))
                        return true;

                    long long wa = 0;
                    long long wb = 0;
                    if (variant == 0) {
                        wa = D_SUSC[pa.r][pa.c];
                        wb = D_SUSC[pb.r][pb.c];
                    } else if (variant == 1) {
                        wa = -D_SUSC[pa.r][pa.c];
                        wb = -D_SUSC[pb.r][pb.c];
                    } else {
                        const int bias = (variant == 4 ? 3 : 7);
                        wa = bias * D_SUSC[pa.r][pa.c] +
                             (u.r * 17 + u.c * 31 + a * 13) % 19;
                        wb = bias * D_SUSC[pb.r][pb.c] +
                             (u.r * 17 + u.c * 31 + b * 13) % 19;
                    }
                    return wa > wb;
                });
            } else if (variant == 3) {
                dirs = {1, 2, 3, 0};
            }

            return dirs;
        };

        std::queue<int> q;
        parent[0] = 0;
        q.push(0);

        while (!q.empty()) {
            int uid = q.front();
            q.pop();
            order.push_back(uid);

            Pos u = pos_of(uid);
            for (int dir : ordered_dirs(u)) {
                Pos v{static_cast<int16_t>(u.r + DR[dir]),
                      static_cast<int16_t>(u.c + DC[dir])};

                if (!is_valid_pos(v.r, v.c) || check_wall(u, v))
                    continue;

                int vid = id_of(v.r, v.c);
                if (parent[vid] != -1)
                    continue;

                parent[vid] = uid;
                depth[vid] = depth[uid] + 1;
                children[uid].push_back(vid);
                q.push(vid);
            }
        }

        if (static_cast<int>(order.size()) != cells)
            continue;

        std::vector<long long> demand(cells, 0);
        for (int i = cells - 1; i >= 0; --i) {
            int u = order[i];
            demand[u] += D_SUSC[u / N_GRID_SIZE][u % N_GRID_SIZE];
            if (u != 0)
                demand[parent[u]] += demand[u];
        }

        std::vector<char> route;
        route.reserve(std::min(MAX_L_PATH, cells * 8));

        std::function<void(int)> append_full_euler = [&](int u) {
            Pos pu = pos_of(u);
            for (int v : children[u]) {
                Pos pv = pos_of(v);
                route.push_back(get_move_char(pu, pv));
                append_full_euler(v);
                route.push_back(get_move_char(pv, pu));
            }
        };
        append_full_euler(0);

        auto make_root_path = [&](int u) {
            std::vector<char> path;
            while (u != 0) {
                int p = parent[u];
                path.push_back(get_move_char(pos_of(p), pos_of(u)));
                u = p;
            }
            std::reverse(path.begin(), path.end());
            return path;
        };

        auto make_subtree_walk = [&](int root) {
            std::vector<char> walk;
            std::function<void(int)> dfs = [&](int u) {
                Pos pu = pos_of(u);
                for (int v : children[u]) {
                    Pos pv = pos_of(v);
                    walk.push_back(get_move_char(pu, pv));
                    dfs(v);
                    walk.push_back(get_move_char(pv, pu));
                }
            };
            dfs(root);
            return walk;
        };

        std::vector<long double> age(cells, 1.0L);
        for (int u = 1; u < cells; ++u)
            age[u] = static_cast<long double>(depth[u] + 1);

        // A hard cap prevents excessive repeated excursions while still
        // allowing many visits to high-demand regions.
        for (int excursion = 0; excursion < 20000; ++excursion) {
            int selected = -1;
            long double selected_value = -1.0L;
            std::vector<char> selected_outward;
            std::vector<char> selected_inside;
            long long selected_length = 0;

            for (int u = 1; u < cells; ++u) {
                const long long cost = 2LL * depth[u];
                if (cost <= 0)
                    continue;

                long double priority =
                    static_cast<long double>(demand[u]) *
                    (age[u] + static_cast<long double>(cost)) *
                    (age[u] + static_cast<long double>(cost)) /
                    static_cast<long double>(cost);

                if (priority <= selected_value)
                    continue;

                std::vector<char> outward = make_root_path(u);
                std::vector<char> inside = make_subtree_walk(u);
                long long length =
                    2LL * outward.size() + static_cast<long long>(inside.size());

                if (route.size() + length > 95000)
                    continue;

                selected = u;
                selected_value = priority;
                selected_length = length;
                selected_outward = std::move(outward);
                selected_inside = std::move(inside);
            }

            if (selected < 0)
                break;

            route.insert(route.end(),
                         selected_outward.begin(),
                         selected_outward.end());
            route.insert(route.end(),
                         selected_inside.begin(),
                         selected_inside.end());

            for (auto it = selected_outward.rbegin();
                 it != selected_outward.rend(); ++it) {
                route.push_back(invert_move(*it));
            }

            std::vector<unsigned char> serviced(cells, 0);
            std::vector<int> stack(1, selected);
            while (!stack.empty()) {
                int u = stack.back();
                stack.pop_back();
                serviced[u] = 1;
                for (int v : children[u])
                    stack.push_back(v);
            }

            for (int u = 1; u < cells; ++u) {
                if (serviced[u])
                    age[u] = 0.0L;
                else
                    age[u] += static_cast<long double>(selected_length);
            }
        }

        if (route.size() > MAX_L_PATH)
            continue;

        PathData candidate;
        candidate.moves = std::move(route);
        calculate_score_full(candidate);

        if (candidate.score_val < best.score_val)
            best = std::move(candidate);
    }

    return best;
}

/**
 * Relocate repeated visits of high-contribution cells.
 *
 * The routine ranks cells by their exact dirt contribution, removes one
 * redundant occurrence, reconnects its neighbors with APSP, and inserts a
 * shortest-path round trip to the same cell at the midpoint of its largest
 * remaining cyclic visit gap.  Candidates are retained only after exact
 * rescoring.
 */
PathData relocate_visit_occurrences(
    PathData incumbent,
    const std::chrono::high_resolution_clock::time_point& start_time,
    double time_limit_seconds) {
    const int cells = N_GRID_SIZE * N_GRID_SIZE;
    const double deadline = std::min(1.80, time_limit_seconds - 0.20);
    int accepted = 0;

    for (int pass = 0; pass < 4 && accepted < 40; ++pass) {
        auto timed_out = [&]() {
            auto now = std::chrono::high_resolution_clock::now();
            return std::chrono::duration<double>(now - start_time).count() >
                   deadline;
        };
        if (timed_out()) break;

        std::vector<int> ranked(cells);
        std::iota(ranked.begin(), ranked.end(), 0);
        std::sort(ranked.begin(), ranked.end(), [&](int a, int b) {
            const int ar = a / N_GRID_SIZE, ac = a % N_GRID_SIZE;
            const int br = b / N_GRID_SIZE, bc = b % N_GRID_SIZE;
            const long double va =
                static_cast<long double>(D_SUSC[ar][ac]) *
                incumbent.cell_dirt_term_sum[ar][ac];
            const long double vb =
                static_cast<long double>(D_SUSC[br][bc]) *
                incumbent.cell_dirt_term_sum[br][bc];
            return va > vb;
        });

        bool improved = false;
        for (int rank = 0; rank < std::min(cells, 120) &&
                            accepted < 40 && !timed_out(); ++rank) {
            const int id = ranked[rank];
            const Pos target{static_cast<int16_t>(id / N_GRID_SIZE),
                             static_cast<int16_t>(id % N_GRID_SIZE)};

            std::vector<int> occurrences;
            for (int t = 1; t < static_cast<int>(incumbent.coords.size()) - 1;
                 ++t) {
                if (incumbent.coords[t] == target)
                    occurrences.push_back(t);
            }
            if (occurrences.size() < 2) continue;

            const int limit = std::min<int>(12, occurrences.size());
            for (int oi = 0; oi < limit && accepted < 40 && !timed_out();
                 ++oi) {
                const int removed = occurrences[oi];
                const Pos before = incumbent.coords[removed - 1];
                const Pos after = incumbent.coords[removed + 1];

                std::vector<char> reconnect;
                if (!get_apsp_moves(before, after, reconnect))
                    continue;

                std::vector<int> remaining;
                remaining.reserve(occurrences.size() - 1);
                for (int t : occurrences)
                    if (t != removed) remaining.push_back(t);
                if (remaining.empty()) continue;

                const int old_length =
                    static_cast<int>(incumbent.moves.size());

                int gap_start = remaining.back();
                int largest_gap =
                    remaining.front() + old_length - remaining.back();
                for (size_t k = 1; k < remaining.size(); ++k) {
                    const int gap = remaining[k] - remaining[k - 1];
                    if (gap > largest_gap) {
                        largest_gap = gap;
                        gap_start = remaining[k - 1];
                    }
                }

                int midpoint = (gap_start + largest_gap / 2) % old_length;
                if (midpoint == removed || midpoint == removed - 1)
                    midpoint = (midpoint + 1) % old_length;

                const Pos anchor = incumbent.coords[midpoint];
                std::vector<char> outward, inward;
                if (!get_apsp_moves(anchor, target, outward) ||
                    !get_apsp_moves(target, anchor, inward))
                    continue;

                PathData candidate = incumbent;
                candidate.moves.erase(candidate.moves.begin() + removed - 1,
                                      candidate.moves.begin() + removed + 1);
                candidate.moves.insert(candidate.moves.begin() + removed - 1,
                                       reconnect.begin(), reconnect.end());

                int insertion = midpoint;
                if (insertion >= removed + 1)
                    insertion -= 2;
                insertion = std::max(
                    0, std::min(insertion,
                                static_cast<int>(candidate.moves.size())));

                candidate.moves.insert(candidate.moves.begin() + insertion,
                                       outward.begin(), outward.end());
                candidate.moves.insert(
                    candidate.moves.begin() + insertion + outward.size(),
                    inward.begin(), inward.end());

                if (candidate.moves.size() > MAX_L_PATH)
                    continue;

                calculate_score_full(candidate);
                if (candidate.score_val < incumbent.score_val) {
                    incumbent = std::move(candidate);
                    ++accepted;
                    improved = true;
                    break;
                }
            }
            if (improved) break;
        }

        if (!improved) break;
    }
    return incumbent;
}

int main(int argc, char *argv[]) {
    std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);

    double time_limit_seconds = 1.95; 
    if (argc > 1) time_limit_seconds = std::stod(argv[1]);

    auto time_start_prog = std::chrono::high_resolution_clock::now();
    RND_ENGINE.seed(std::chrono::system_clock::now().time_since_epoch().count());

    std::cin >> N_GRID_SIZE;
    H_WALLS_INFO.resize(N_GRID_SIZE - 1); 
    V_WALLS_INFO.resize(N_GRID_SIZE);     

    for (int i = 0; i < N_GRID_SIZE - 1; ++i) std::cin >> H_WALLS_INFO[i];
    for (int i = 0; i < N_GRID_SIZE; ++i) std::cin >> V_WALLS_INFO[i]; 
    for (int i = 0; i < N_GRID_SIZE; ++i) for (int j = 0; j < N_GRID_SIZE; ++j) std::cin >> D_SUSC[i][j];

    MAX_L_PATH_HIGH_THRESHOLD_EFFECTIVE = MAX_L_PATH * 0.95; 
    MIN_L_PATH_LOW_THRESHOLD_EFFECTIVE = N_GRID_SIZE * N_GRID_SIZE; 

    compute_apsp();

    CELL_VISIT_TIMES_GLOBAL_BUFFER.resize(N_GRID_SIZE);
    TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.reserve(N_GRID_SIZE * N_GRID_SIZE);
    for(int r=0; r<N_GRID_SIZE; ++r) {
        CELL_VISIT_TIMES_GLOBAL_BUFFER[r].resize(N_GRID_SIZE);
        int reserve_size = std::max(2, MAX_L_PATH / (N_GRID_SIZE*N_GRID_SIZE) + 50);
         if (reserve_size > MAX_L_PATH / 2 && MAX_L_PATH > 2) reserve_size = MAX_L_PATH/2; // Cap reasonable max
        for(int c=0; c<N_GRID_SIZE; ++c) {
             CELL_VISIT_TIMES_GLOBAL_BUFFER[r][c].reserve(reserve_size);
        }
    }
    GET_APSP_MOVES_BUFFER1.reserve(N_GRID_SIZE*N_GRID_SIZE*2); 
    GET_APSP_MOVES_BUFFER2.reserve(N_GRID_SIZE*N_GRID_SIZE*2);


    PathData current_pd_obj;
    for(int i=0; i<N_GRID_SIZE; ++i)
        for(int j=0; j<N_GRID_SIZE; ++j)
            initial_dfs_visited[i][j] = false;

    PathData service_seed = generate_service_schedule_seed();
    PathData circulation_seed = generate_weighted_tree_circulation();

    if (service_seed.score_val < 1e17L &&
        service_seed.score_val <= circulation_seed.score_val) {
        current_pd_obj = std::move(service_seed);
    } else if (circulation_seed.score_val < 1e17L) {
        current_pd_obj = std::move(circulation_seed);
    } else {
        generate_initial_dfs_path(0, 0, current_pd_obj);
        calculate_score_full(current_pd_obj);
    }

    PathData best_pd_obj = current_pd_obj;
    best_pd_obj = relocate_visit_occurrences(
        best_pd_obj, time_start_prog, time_limit_seconds);
    current_pd_obj = best_pd_obj;

    double start_temp = 5000.0 * sqrt(N_GRID_SIZE);
    double end_temp = 0.1;    

    int iterations_count = 0;
    PathData candidate_pd_obj; 
    std::uniform_real_distribution<double> accept_dist_01(0.0, 1.0);


    while(true) {
        iterations_count++;
        if(iterations_count % 100 == 0){ 
            auto now_time = std::chrono::high_resolution_clock::now();
            double elapsed_seconds = std::chrono::duration<double>(now_time - time_start_prog).count();
            if (elapsed_seconds > time_limit_seconds) break;
        }

        int L_curr = current_pd_obj.moves.size();

        bool modified_successfully = false;
        for (int try_op = 0; try_op < 10; ++try_op) { 
            candidate_pd_obj = current_pd_obj; 

            std::uniform_int_distribution<int> op_dist(0, 99); 
            int op_choice_val = op_dist(RND_ENGINE);
            int operation_type = -1;

            if (op_choice_val < 15) operation_type = 0;      
            else if (op_choice_val < 30) operation_type = 1; 
            else if (op_choice_val < 60) operation_type = 2; 
            else if (op_choice_val < 70) operation_type = 3; 
            else if (op_choice_val < 85) operation_type = 4;                       
            else operation_type = 5;                         

            bool is_length_increasing_op = (operation_type == 0 || operation_type == 4); 
            // Op5 can increase or decrease length. Check its specific outcome for length control.
            bool is_length_decreasing_op = (operation_type == 1 || operation_type == 2); 

            if (is_length_increasing_op && L_curr > MAX_L_PATH_HIGH_THRESHOLD_EFFECTIVE) {
                if (accept_dist_01(RND_ENGINE) < 0.75) continue; 
            }
            if (is_length_decreasing_op && L_curr < MIN_L_PATH_LOW_THRESHOLD_EFFECTIVE) {
                 if (accept_dist_01(RND_ENGINE) < 0.75) continue; 
            }


            if (operation_type == 0) { 
                if (L_curr == 0 && N_GRID_SIZE > 1) continue; 
                if (candidate_pd_obj.moves.size() + 2 > MAX_L_PATH) continue; 
                if (current_pd_obj.coords.empty() && N_GRID_SIZE > 1) continue;

                std::uniform_int_distribution<int> k_idx_dist(0, L_curr); 
                int k_coord_idx = k_idx_dist(RND_ENGINE); 
                Pos p_k = current_pd_obj.coords[k_coord_idx]; 

                std::vector<int> possible_dirs; possible_dirs.reserve(4);
                for(int dir_i=0; dir_i<4; ++dir_i) {
                    Pos neighbor_p = Pos{(int16_t)(p_k.r + DR[dir_i]), (int16_t)(p_k.c + DC[dir_i])};
                    if (is_valid_pos(neighbor_p.r, neighbor_p.c) && !check_wall(p_k, neighbor_p)) {
                        possible_dirs.push_back(dir_i);
                    }
                }
                if (possible_dirs.empty()) continue;
                std::uniform_int_distribution<int> dir_choice_dist(0, possible_dirs.size()-1);
                int random_dir_idx = possible_dirs[dir_choice_dist(RND_ENGINE)];

                candidate_pd_obj.moves.insert(candidate_pd_obj.moves.begin() + k_coord_idx, 
                                             {DIR_CHARS[random_dir_idx], DIR_CHARS[(random_dir_idx+2)%4]});
            } else if (operation_type == 1) { 
                if (L_curr < 2) continue; 
                if (current_pd_obj.coords.size() < 3) continue; 

                std::vector<int> possible_indices; possible_indices.reserve(L_curr); 
                for(int k_m_idx = 0; k_m_idx <= L_curr - 2; ++k_m_idx) { 
                    if (current_pd_obj.coords[k_m_idx] == current_pd_obj.coords[k_m_idx+2]) {
                        possible_indices.push_back(k_m_idx);
                    }
                }
                if (possible_indices.empty()) continue;
                std::uniform_int_distribution<int> idx_choice_dist(0, possible_indices.size()-1);
                int k_move_idx_to_remove = possible_indices[idx_choice_dist(RND_ENGINE)];

                candidate_pd_obj.moves.erase(candidate_pd_obj.moves.begin() + k_move_idx_to_remove, 
                                             candidate_pd_obj.moves.begin() + k_move_idx_to_remove + 2);
            } else if (operation_type == 2) { 
                if (L_curr < 1) continue; 

                std::uniform_int_distribution<int> c_idx1_dist(0, L_curr > 0 ? L_curr - 1 : 0); 
                int c_idx1 = c_idx1_dist(RND_ENGINE); 
                std::uniform_int_distribution<int> c_idx2_dist(c_idx1 + 1, L_curr); 
                int c_idx2 = c_idx2_dist(RND_ENGINE);
                if (c_idx1 >= c_idx2 && L_curr > 0) continue; // Need valid subsegment
                if (L_curr == 0 && (c_idx1!=0 || c_idx2!=0)) continue; // L=0 means c_idx1=0, c_idx2=0 only

                Pos p_A = current_pd_obj.coords[c_idx1]; Pos p_B = current_pd_obj.coords[c_idx2];

                if (!get_apsp_moves(p_A, p_B, GET_APSP_MOVES_BUFFER1)) continue;

                if (GET_APSP_MOVES_BUFFER1.size() >= (size_t)(c_idx2 - c_idx1) && L_curr > 0 ) continue; // APSP not shorter (allow if L_curr=0)

                if ( ( (long long)candidate_pd_obj.moves.size() - (c_idx2 - c_idx1) + GET_APSP_MOVES_BUFFER1.size()) > MAX_L_PATH) continue;

                if (c_idx1 < c_idx2) { // Ensure erase range is valid
                    candidate_pd_obj.moves.erase(candidate_pd_obj.moves.begin() + c_idx1, 
                                                candidate_pd_obj.moves.begin() + c_idx2);
                }
                candidate_pd_obj.moves.insert(candidate_pd_obj.moves.begin() + c_idx1, 
                                              GET_APSP_MOVES_BUFFER1.begin(), GET_APSP_MOVES_BUFFER1.end());
            } else if (operation_type == 3) { 
                if (L_curr < 1) continue; 

                std::uniform_int_distribution<int> move_idx_dist(0, L_curr -1);
                int move_idx1 = move_idx_dist(RND_ENGINE); 
                std::uniform_int_distribution<int> move_idx_dist2(move_idx1, L_curr -1); 
                int move_idx2_inclusive = move_idx_dist2(RND_ENGINE);

                int move_idx2_exclusive = move_idx2_inclusive + 1;

                std::reverse(candidate_pd_obj.moves.begin() + move_idx1, candidate_pd_obj.moves.begin() + move_idx2_exclusive);
                for(int i = move_idx1; i < move_idx2_exclusive; ++i) 
                    candidate_pd_obj.moves[i] = invert_move(candidate_pd_obj.moves[i]);

            } else if (operation_type == 4) { 
                if (L_curr == 0 && N_GRID_SIZE > 1) continue; 
                if (current_pd_obj.coords.empty() && N_GRID_SIZE > 1) continue; 

                Pos target_cell = select_target_cell_for_dirt_ops(current_pd_obj, false);

                int best_k_coord_idx = -1;
                long long min_detour_len_increase = (long long)MAX_L_PATH * 2 +1; // path len increase: 2 for wiggle, 2*dist for detour

                if (L_curr >= 0) { // Path can be empty (L_curr=0), then coords has 1 element (0,0)
                    int num_samples = (L_curr == 0) ? 1: OP4_SAMPLE_POINTS; // If L_curr=0, only one point to pick: coords[0]
                    for (int i=0; i < num_samples; ++i) {
                        std::uniform_int_distribution<int> k_idx_dist(0, L_curr); 
                        int k_coord_idx_sample = (L_curr == 0) ? 0 : k_idx_dist(RND_ENGINE);
                        Pos p_A_sample = current_pd_obj.coords[k_coord_idx_sample];

                        long long current_detour_increase;
                        if (p_A_sample == target_cell) {
                             current_detour_increase = 2; // Wiggle cost
                        } else {
